#!/bin/sh
# Prepare a pinned OpenWrt tree, sync RouterOS service defaults and register its feed.
# Network and system configuration are generated by OpenWrt for the selected board.

set -eu

ROOT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
OPENWRT_DIR=${OPENWRT_DIR:-"$ROOT_DIR/openwrt"}
OPENWRT_REF=${OPENWRT_REF:-v25.12.6}
CUSTOM_FEED_DIR="$ROOT_DIR/custom-feed"
OVERLAY_DIR="$ROOT_DIR/custom/overlay"
MANIFEST="$OPENWRT_DIR/.routeros-overlay.sha256"
TMP_MANIFEST="$OPENWRT_DIR/.routeros-overlay.sha256.tmp.$$"

# Allow overriding source root for external repositories
ROUTEROS_SOURCE_ROOT=${ROUTEROS_SOURCE_ROOT:-"$ROOT_DIR"}

fail() {
	printf 'ERROR: %s\n' "$*" >&2
	exit 1
}

cleanup() {
	rm -f "$TMP_MANIFEST"
}
trap cleanup EXIT HUP INT TERM

command -v git >/dev/null 2>&1 || fail "git is required"
command -v sha256sum >/dev/null 2>&1 || fail "sha256sum is required"
[ -d "$CUSTOM_FEED_DIR" ] || fail "custom-feed directory is missing"
[ -d "$OVERLAY_DIR" ] || fail "custom/overlay directory is missing"

if [ ! -d "$OPENWRT_DIR" ]; then
	printf 'Cloning OpenWrt %s into %s\n' "$OPENWRT_REF" "$OPENWRT_DIR"
	git clone --depth 1 --branch "$OPENWRT_REF" https://github.com/openwrt/openwrt.git "$OPENWRT_DIR"
fi

[ -d "$OPENWRT_DIR/.git" ] || fail "$OPENWRT_DIR exists but is not an OpenWrt Git checkout"
actual_commit=$(git -C "$OPENWRT_DIR" rev-parse HEAD)
expected_commit=$(git -C "$OPENWRT_DIR" rev-parse "$OPENWRT_REF^{commit}" 2>/dev/null || true)
[ -n "$expected_commit" ] || fail "OpenWrt ref $OPENWRT_REF is not available locally; fetch it or remove the checkout and rerun setup"
[ "$actual_commit" = "$expected_commit" ] || fail "OpenWrt checkout is not at $OPENWRT_REF (HEAD=$actual_commit). No files were changed; check out the pinned ref and rerun."

FEEDS_CONF="$OPENWRT_DIR/feeds.conf"
CUSTOM_FEED_LINE="src-link routeros $CUSTOM_FEED_DIR"
DEFAULTS_LINE="src-include defaults feeds.conf.default"

# Check if feeds.conf already exists and is configured by RouterOS
if [ -f "$FEEDS_CONF" ]; then
	# If feeds.conf exists and contains local feeds, assume it's already configured
	if grep -q "src-git packages $ROOT_DIR/packages" "$FEEDS_CONF" 2>/dev/null; then
		printf 'Local feeds already configured in %s\n' "$FEEDS_CONF"
	else
		# Old-style configuration - require manual update
		grep -Fqx "$CUSTOM_FEED_LINE" "$FEEDS_CONF" ||
			fail "existing feeds.conf was preserved. Add this exact line to it: $CUSTOM_FEED_LINE"
		grep -Fqx "$DEFAULTS_LINE" "$FEEDS_CONF" ||
			fail "existing feeds.conf must include upstream pinned feeds with: $DEFAULTS_LINE"
	fi
else
	# Create feeds.conf with local feeds prioritized
	if [ -d "$ROUTEROS_SOURCE_ROOT/packages" ] && [ -d "$ROUTEROS_SOURCE_ROOT/luci" ] && [ -d "$ROUTEROS_SOURCE_ROOT/routing" ]; then
		printf 'Configuring local feeds (packages, luci, routing)\n'
		printf 'Source root: %s\n' "$ROUTEROS_SOURCE_ROOT"
		cat > "$FEEDS_CONF" <<EOF
# RouterOS local feed configuration
# Local feeds are prioritized for development and reproducibility
# Remote feeds are kept as fallback for missing packages

# Local feeds (prioritized)
src-git packages $ROUTEROS_SOURCE_ROOT/packages
src-git luci $ROUTEROS_SOURCE_ROOT/luci
src-git routing $ROUTEROS_SOURCE_ROOT/routing

# RouterOS custom feed
src-link routeros $CUSTOM_FEED_DIR

# Remote feeds (fallback)
src-git telephony https://git.openwrt.org/feed/telephony.git
src-git video https://github.com/openwrt/video.git

# Include OpenWrt defaults for any feeds not defined above
src-include defaults feeds.conf.default
EOF
	else
		# Fallback to remote feeds if local feeds not available
		printf 'Local feeds not found, using remote feeds\n'
		{
			printf '%s\n' "$DEFAULTS_LINE"
			printf '%s\n' "$CUSTOM_FEED_LINE"
		} > "$FEEDS_CONF"
	fi
fi

# OpenWrt's first-boot config_generate must be allowed to create /etc/config/
# network and system from the selected board's board.json and board.d scripts.
# Older RouterOS revisions installed static files for both and suppressed that
# board-aware generation. Remove only files still byte-identical to the old
# managed copies; refuse unknown or locally modified files.
mkdir -p "$OPENWRT_DIR/files"
for name in network system; do
	relative_path="etc/config/$name"
	target_file="$OPENWRT_DIR/files/$relative_path"
	old_hash=$(awk -v path="$relative_path" '$2 == path { print $1; exit }' "$MANIFEST" 2>/dev/null || true)

	if [ -L "$target_file" ]; then
		fail "retired overlay target is a symbolic link; refusing to remove it: $target_file"
	elif [ -e "$target_file" ]; then
		[ -f "$target_file" ] || fail "retired overlay target is not a regular file: $target_file"
		[ -n "$old_hash" ] ||
			fail "unmanaged network/system overlay exists; move or review it manually before building: $target_file"
		current_hash=$(sha256sum "$target_file" | awk '{ print $1 }')
		[ "$current_hash" = "$old_hash" ] ||
			fail "retired overlay was locally modified; preserve or review it manually: $target_file"
		rm -f "$target_file"
		printf 'Removed retired managed overlay: %s\n' "$relative_path"
	fi
done

# Only service defaults that are independent of the board's physical topology
# are shared through the rootfs overlay.
: > "$TMP_MANIFEST"
for name in firewall dhcp; do
	relative_path="etc/config/$name"
	source_file="$OVERLAY_DIR/$relative_path"
	target_file="$OPENWRT_DIR/files/$relative_path"

	[ -f "$source_file" ] || fail "rootfs overlay source is missing: $source_file"
	mkdir -p "$(dirname "$target_file")"

	new_hash=$(sha256sum "$source_file" | awk '{ print $1 }')
	old_hash=$(awk -v path="$relative_path" '$2 == path { print $1; exit }' "$MANIFEST" 2>/dev/null || true)
	current_hash=

	if [ -L "$target_file" ]; then
		fail "overlay target is a symbolic link; refusing to replace it: $target_file"
	elif [ -e "$target_file" ]; then
		[ -f "$target_file" ] || fail "overlay target is not a regular file: $target_file"
		current_hash=$(sha256sum "$target_file" | awk '{ print $1 }')
		if [ -n "$old_hash" ]; then
			[ "$current_hash" = "$old_hash" ] || [ "$current_hash" = "$new_hash" ] ||
				fail "overlay target was locally modified; preserve or merge it manually: $target_file"
		else
			[ "$current_hash" = "$new_hash" ] ||
				fail "pre-existing OpenWrt overlay conflicts with RouterOS: $target_file"
		fi
	fi

	if [ "$current_hash" != "$new_hash" ]; then
		temporary_file="$target_file.routeros-tmp.$$"
		cp "$source_file" "$temporary_file"
		chmod 0644 "$temporary_file"
		mv "$temporary_file" "$target_file"
	fi

	printf '%s  %s\n' "$new_hash" "$relative_path" >> "$TMP_MANIFEST"
done

mv "$TMP_MANIFEST" "$MANIFEST"

printf '\nRouterOS build tree is ready.\n'
printf '  OpenWrt ref: %s\n' "$OPENWRT_REF"
printf '  OpenWrt commit: %s\n' "$actual_commit"
printf '  Custom feed: %s\n' "$CUSTOM_FEED_DIR"
printf '  Shared service overlay: %s/files\n' "$OPENWRT_DIR"
printf '  Network/system config: generated by OpenWrt for the selected board\n'
printf '\nNext: cd "%s" && ./scripts/feeds update -a\n' "$OPENWRT_DIR"
